#pragma once
#include <pthread.h>
#include <signal.h>
#include <unistd.h>
#include <cerrno>
#include <cstddef>
namespace ii::gui::detail {
// A Wayland receiver may close its pipe at any time. Mask SIGPIPE only on the
// writing thread and consume only the signal generated by this write. Never
// replace the application's process-wide signal disposition.
inline ssize_t pipe_write(int fd,const void* data,std::size_t count)noexcept{
    sigset_t set,previous,pending;sigemptyset(&set);sigaddset(&set,SIGPIPE);
    const auto error=pthread_sigmask(SIG_BLOCK,&set,&previous);if(error){errno=error;return -1;}
    sigpending(&pending);const bool already=sigismember(&pending,SIGPIPE)==1;
    const auto result=::write(fd,data,count);const auto saved=errno;
    if(result<0&&saved==EPIPE&&!already){sigpending(&pending);if(sigismember(&pending,SIGPIPE)==1){int signal=0;(void)sigwait(&set,&signal);}}
    (void)pthread_sigmask(SIG_SETMASK,&previous,nullptr);errno=saved;return result;
}
}
